targets.expr:
avg((time() - (max by (cluster, hosted_cluster_namespace) (
  label_replace(
    max without (prometheus_replica) (
      velero_backup_last_successful_timestamp{cluster="$cluster", schedule=~"${hcp_namespace:regex}-6-hourly"}
    ),
    "hosted_cluster_namespace", "$1", "schedule", "(.+)-6-hourly"
  )
) or max by (cluster, hosted_cluster_namespace) (
  label_replace(
    max without (prometheus_replica) (
      velero_backup_last_status{cluster="$cluster", schedule=~"${hcp_namespace:regex}-6-hourly"}
    ) * 0,
    "hosted_cluster_namespace", "$1", "schedule", "(.+)-6-hourly"
  )
))) <= bool 12 * 3600) * 100

clamp_max(max((time() - (max by (cluster, hosted_cluster_namespace) (
  label_replace(
    max without (prometheus_replica) (
      velero_backup_last_successful_timestamp{cluster="$cluster", schedule=~"${hcp_namespace:regex}-6-hourly"}
    ),
    "hosted_cluster_namespace", "$1", "schedule", "(.+)-6-hourly"
  )
) or max by (cluster, hosted_cluster_namespace) (
  label_replace(
    max without (prometheus_replica) (
      velero_backup_last_status{cluster="$cluster", schedule=~"${hcp_namespace:regex}-6-hourly"}
    ) * 0,
    "hosted_cluster_namespace", "$1", "schedule", "(.+)-6-hourly"
  )
))) / 3600), 168)

clamp_max((time() - (max by (cluster, hosted_cluster_namespace) (
  label_replace(
    max without (prometheus_replica) (
      velero_backup_last_successful_timestamp{cluster="$cluster", schedule=~"${hcp_namespace:regex}-6-hourly"}
    ),
    "hosted_cluster_namespace", "$1", "schedule", "(.+)-6-hourly"
  )
) or max by (cluster, hosted_cluster_namespace) (
  label_replace(
    max without (prometheus_replica) (
      velero_backup_last_status{cluster="$cluster", schedule=~"${hcp_namespace:regex}-6-hourly"}
    ) * 0,
    "hosted_cluster_namespace", "$1", "schedule", "(.+)-6-hourly"
  )
)))/3600, 168)

count by (cluster) (
  count by (cluster, hosted_cluster_namespace) (
    label_replace(
      max without (prometheus_replica) (
        velero_backup_last_status{
          cluster="$cluster",
          schedule=~".+-(6-hourly|daily|weekly)"
        }
      ),
      "hosted_cluster_namespace", "$1",
      "schedule", "(.+)-(6-hourly|daily|weekly)"
    )
  )
)

(
  time()
  -
  (
    max by (cluster, schedule) (
      max without (prometheus_replica) (
        velero_backup_last_successful_timestamp{
          cluster="$cluster",
          schedule=~"${hcp_namespace:regex}-(6-hourly|daily|weekly)"
        }
      )
    )
    or
    max by (cluster, schedule) (
      max without (prometheus_replica) (
        velero_backup_last_status{
          cluster="$cluster",
          schedule=~"${hcp_namespace:regex}-(6-hourly|daily|weekly)"
        }
      ) * 0
    )
  )
) / 3600

count by (cluster) (
  max without (prometheus_replica) (
    velero_backup_last_status{cluster="$cluster", schedule=~".+-(6-hourly|daily|weekly)"}
  )
  unless
  max without (prometheus_replica) (
    velero_backup_last_successful_timestamp{cluster="$cluster", schedule=~".+-(6-hourly|daily|weekly)"}
  )
)
or
(
  0 *
  count by (cluster) (
    max without (prometheus_replica) (
      velero_backup_last_status{cluster="$cluster", schedule=~".+-(6-hourly|daily|weekly)"}
    )
  )
)

sum by (cluster) (
  max without (prometheus_replica) (
    velerobackup_phase{
      cluster="$cluster",
      name=~".+-keyrotation-.+",
      phase=~"Failed|PartiallyFailed|FailedValidation"
    }
  )
)

sum(
  max without (prometheus_replica) (
    increase(
      velero_repo_maintenance_failure_total{
        cluster="$cluster"
      }[$__range]
    )
  )
)
